% Compile this block in Overleaf or TeXShop to generate the breadboard layout
\begin{center}
\begin{tikzpicture}[scale=0.85, transform shape]
    % Breadboard Body
    \fill[black!5!white, rounded corners] (0, -4.5) rectangle (14, 4.5);
    \draw[thick, black!30!white, rounded corners] (0, -4.5) rectangle (14, 4.5);

    % Central Trench
    \fill[black!15!white] (1, -0.4) rectangle (13, 0.4);

    % Power Rails (Top)
    \draw[red, thick] (1, 3.5) -- (13, 3.5);
    \draw[blue, thick] (1, 2.8) -- (13, 2.8);
    \node[red, left] at (1, 3.5) {$+$};
    \node[blue, left] at (1, 2.8) {$-$};

    % Power Rails (Bottom) - Flipped Orientation
    \draw[red, thick] (1, -2.8) -- (13, -2.8);
    \draw[blue, thick] (1, -3.5) -- (13, -3.5);
    \node[red, left] at (1, -2.8) {$+$};
    \node[blue, left] at (1, -3.5) {$-$};

    % Breadboard Holes
    \foreach \x in {2,3,...,12} {
        \fill[black!70!white] (\x, 3.25) circle (0.06);
        \fill[black!70!white] (\x, 2.55) circle (0.06);
        \fill[black!70!white] (\x, -2.55) circle (0.06);
        \fill[black!70!white] (\x, -3.25) circle (0.06);
        \foreach \y in {0.7, 1.0, 1.3, 1.6, 1.9} {
            \fill[black!70!white] (\x, \y) circle (0.06);
            \fill[black!70!white] (\x, -\y) circle (0.06);
        }
    }

    % LM741 IC
    \fill[black!80!white, rounded corners=1mm] (6.5, -0.8) rectangle (8.5, 0.8);
    \node[white] at (7.5, 0) {\textbf{LM741}};
    \fill[black] (6.7, 0.5) circle (0.1); 

    \foreach \x/\pin in {6.8/1, 7.2/2, 7.8/3, 8.2/4} { \draw[thick, gray] (\x, -0.8) -- (\x, -1); }
    \foreach \x/\pin in {8.2/5, 7.8/6, 7.2/7, 6.8/8} { \draw[thick, gray] (\x, 0.8) -- (\x, 1); }

    % Wiring Connections
    \draw[red, line width=1.5pt] (2, 5.5) node[above, text=black] {From +10V Supply} to[out=-90, in=90] (2, 3.25);
    \filldraw[red] (2, 3.25) circle (0.1); 

    \draw[red!60!black, line width=1.5pt] (2, -5.5) node[below, text=black] {From -10V Supply} to[out=90, in=-90] (2, -2.55);
    \filldraw[red!60!black] (2, -2.55) circle (0.1); 

    \draw[green!60!black, line width=1.5pt] (6, 5.5) node[above, text=black] {From 0V (GND)} to[out=-90, in=90] (4, 2.55);
    \filldraw[green!60!black] (4, 2.55) circle (0.1); 

    \draw[green!60!black, line width=1.5pt] (11, 2.55) to[out=-90, in=90] (11, -3.25);
    \filldraw[green!60!black] (11, 2.55) circle (0.1);
    \filldraw[green!60!black] (11, -3.25) circle (0.1);

    \draw[red, line width=1.5pt] (7.2, 1.0) to[out=90, in=-90] (7.2, 3.25);
    \filldraw[red] (7.2, 1.0) circle (0.1); \filldraw[red] (7.2, 3.25) circle (0.1);

    \draw[red!60!black, line width=1.5pt] (8.2, -1.0) to[out=-90, in=90] (8.2, -2.55);
    \filldraw[red!60!black] (8.2, -1.0) circle (0.1); \filldraw[red!60!black] (8.2, -2.55) circle (0.1);
\end{tikzpicture}
\end{center}

